// Get the search results from the node directly before this one.
const results = $input.item.json.data || [];

// Extract and deduplicate URLs from the results
const urls = results
  .map(r => r.url)
  .filter(url => url && url.startsWith('http'))
  .filter((url, idx, arr) => arr.indexOf(url) === idx);

// Create the final list of items to pass on.
// WARNING: Notice the 'niche' is missing from this output.
return urls.map(url => ({
  json: {
    url: url,
    status: 'pending',
    created_at: new Date().toISOString(),
    retry_count: 0
  }
}));

// Function to run the code on the n8n input data
for (const item of items) {
    const rawData = item.json;

    // Check if the expected data structure exists
    if (!rawData.data || !rawData.data.markdown) {
        // Skip or handle items without the expected structure
        continue;
    }

    const markdownContent = rawData.data.markdown;
    const metadata = rawData.data.metadata || {};

    // --- Data Extraction using Regex and Metadata ---

    // 1. Company Name (from metadata if available, otherwise fallback)
    const companyName = metadata['og:site_name'] || metadata.title || 'N/A';

    // 2. Website URL (from metadata)
    const websiteUrl = metadata.sourceURL || 'N/A';

    // 3. Email Extraction (Regex)
    // Simple regex to find an email address in the markdown content.
    // NOTE: This will only work if an email is clearly present in the text.
    const emailRegex = /([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/;
    const emailMatch = markdownContent.match(emailRegex);
    const email = emailMatch ? emailMatch[0] : 'Not Found in Content';

    // 4. Name, Job Title, Address (Likely not in this specific markdown, 
    // but demonstrating how you'd look for them with specific regex patterns
    // or by checking metadata if the scraped data came from a contact page/schema)

    // Since this scraped content is generic marketing text, these fields 
    // are unlikely to be found. Use placeholders or advanced AI/NLP techniques 
    // for less structured data.

    // Example: A more complex pattern might be needed for a Name (e.g., looking 
    // for names in common salutations or author fields).
    // The example metadata *does* have a "twitter:data1" that might be a name:
    const name = metadata['twitter:data1'] || 'Not Found'; // -> "Gerald Denor" in your example

    const jobTitle = 'Not Found in Content'; // Requires very specific surrounding text/structure
    const address = 'Not Found in Content'; // Requires structured address data (e.g., street, city, zip)

    // --- Prepare the Output Object ---

    // Create a new object with the extracted fields
    const extractedData = {
        name: name,
        jobTitle: jobTitle,
        email: email,
        companyName: companyName,
        websiteUrl: websiteUrl,
        address: address,
        // You can keep the original markdown/metadata if needed for reference
        // originalTitle: metadata.title 
    };

    // Replace the original item's JSON with the extracted data
    // This is the standard n8n Code node pattern for transforming data
    item.json = extractedData;
}

// Return the modified items array
return items;
